"""Build a capability-overlap map using stable catalogue identities."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent
records = {int(r['id'].split('-')[1]):r for r in json.loads((ROOT/'catalogue.json').read_text())}
rows = []
def add(capability, ids, relationship, opportunity, preserve):
    refs = [records[i] for i in ids]
    rows.append(dict(capability=capability, catalogue_ids=[r['id'] for r in refs], relationship=relationship, consolidation_opportunity=opportunity, distinctions_to_preserve=preserve))

add('FITS reading and writing', [1,7,355,434,524], 'Both independent interfaces and wrappers around CFITSIO.', 'One shared reader/writer layer, header handling, memory mapping and compression service.', 'Astropy is not simply another CFITSIO wrapper; FITS scaling, nulls, masks, extension types and ownership differ.')
add('Scientific arrays and file containers', [4,11,17,494,495,496,497,498], 'Related storage and data-model roles at different layers.', 'Common in-memory arrays, named dimensions and adapters; avoid repeated materialization and conversions.', 'HDF5/Zarr/ASDF/NDF are not interchangeable schemas. Preserve units, WCS, quality and variance rather than only array values.')
add('Tables, joins, catalogue queries and columnar data', [1,414,500,501,502,503,504], 'Overlapping generic table operations with different execution models.', 'Shared typed catalogue objects, joins, filters and query execution.', 'Sky-coordinate joins differ from ordinary equijoins; nulls, masks, units and integer precision matter.')
add('Archive access and local/remote caching', [2,3,24,310,505], 'Complementary access layers with overlapping connection/cache concerns.', 'One resource manager, credentials boundary, download cache and dataset identity scheme.', 'VO discovery, mission archive APIs and filesystem range requests require separate adapters.')
add('Units, constants, epochs and positional transformations', [1,8,9,10,22,23,32,356,357,359,430,431,432], 'Shared lineage and partially overlapping independent implementations.', 'Common physical-quantity, epoch, frame and ephemeris services.', 'SOFA/ERFA ancestry; Earth-orientation tables; leap seconds; observer location; precision and frame conventions.')
